/**
 * TeleDOM v4 — The 100+ Improvement Matrix (REGISTRY, not a static doc).
 *
 * Every improvement is a real, engineering-valuable delta beyond the v4
 * roadmap baseline, with: problem, baseline limitation, external evidence,
 * why it matters, architecture, affected modules, complexity, risk,
 * benefit, tests, benchmark, security implications, version target,
 * priority, and implementation status. The docs/intelligence/IMPROVEMENTS.md
 * document is GENERATED from this registry, and a test asserts ≥100
 * distinct non-trivial improvements — feature inflation is structurally
 * rejected.
 */

export type ImprovementStatus =
  | 'IMPLEMENTED' | 'PARTIAL' | 'DEFERRED-external-infrastructure'
  | 'DEFERRED-platform-limit' | 'RESEARCH-ONLY';

export interface Improvement {
  id: string;
  title: string;
  category: string;
  problem: string;
  baselineLimitation: string;
  externalEvidence: string;
  why: string;
  architecture: string;
  modules: string[];
  complexity: 'low' | 'medium' | 'high';
  risk: 'low' | 'medium' | 'high';
  benefit: string;
  tests: string;
  benchmark?: string;
  security: string;
  version: string;
  priority: 'P0' | 'P1' | 'P2' | 'P3';
  status: ImprovementStatus;
}

