/** Validation: at least 100 DISTINCT, NON-TRIVIAL improvements. */
export function validateImprovements(): { valid: boolean; count: number; problems: string[] } {
  const problems: string[] = [];
  const ids = IMPROVEMENTS.map((i) => i.id);
  if (ids.length < 100) problems.push(`expected at least 100 improvements, found ${ids.length}`);
  const dupes = ids.filter((id, i) => ids.indexOf(id) !== i);
  if (dupes.length) problems.push(`duplicate ids: ${dupes.join(', ')}`);
  const trivial = IMPROVEMENTS.filter((i) => i.title.length < 10 || i.problem.length < 20 || i.why.length < 20);
  if (trivial.length) problems.push(`trivial entries: ${trivial.map((t) => t.id).join(', ')}`);
  return { valid: problems.length === 0, count: IMPROVEMENTS.length, problems };
}

export function improvementsByStatus(): Record<ImprovementStatus, number> {
  const out: Record<string, number> = {};
  for (const i of IMPROVEMENTS) out[i.status] = (out[i.status] ?? 0) + 1;
  return out as Record<ImprovementStatus, number>;
}
